('dbbfd188-5de2-472b-a057-d8305d481631', 'Professional Work Placement / Placement en milieu de travail', 'DRCA4975', 3.0, '(Crosslisted to: GL/SOSC 4975 3.00, GL/BIOL 4975 3.00, GL/CDNS 4975 3.00, GL/FRAN 4975 3.00, GL/POLS 4975 3.00, GL/SOCI 4975 3.00, GL/GWST 4975 3.00)', 'GL', 'F'),
('316b9db1-0e56-497d-a5da-367459a720e4', 'Professional Work Placement / Placement en milieu de travail', 'DRCA4975', 3.0, '(Crosslisted to: GL/SOSC 4975 3.00, GL/BIOL 4975 3.00, GL/CDNS 4975 3.00, GL/FRAN 4975 3.00, GL/POLS 4975 3.00, GL/SOCI 4975 3.00, GL/GWST 4975 3.00)', 'GL', 'W'),
('8acfb477-83d2-4620-94c2-022756843fff', 'Professional Work Placement / Placement en milieu de travail', 'DRCA4975', 3.0, '(Crosslisted to: GL/SOSC 4975 3.00, GL/BIOL 4975 3.00, GL/CDNS 4975 3.00, GL/FRAN 4975 3.00, GL/POLS 4975 3.00, GL/SOCI 4975 3.00, GL/GWST 4975 3.00)', 'GL', 'Y'),
